const dados = $input.first().json;

// Suporte a entrada por voz (texto transcrito) ou formulário
const tipo = dados.tipo || 'prescricao'; // 'prescricao' ou 'laudo'
const paciente = dados.paciente || {};
const info_clinica = dados.info_clinica || dados.descricao || dados.texto || '';

return [{
  json: {
    tipo,
    paciente: {
      nome: paciente.nome || dados.nomePaciente || '',
      cpf: paciente.cpf || dados.cpf || '',
      dataNascimento: paciente.dataNascimento || dados.dataNascimento || '',
      telefone: paciente.telefone || dados.telefone || ''
    },
    info_clinica,
    dataEmissao: new Date().toLocaleDateString('pt-BR'),
    numeroDocumento: 'DOC-' + Date.now()
  }
}];

