const claudeResult = $input.first().json;
const htmlDoc = claudeResult.content[0].text;
const dadosOriginais = $('Prepara Dados do Documento').item.json;

return [{
  json: {
    htmlContent: htmlDoc,
    tipo: dadosOriginais.tipo,
    nomePaciente: dadosOriginais.paciente.nome,
    telefone: dadosOriginais.paciente.telefone,
    numeroDocumento: dadosOriginais.numeroDocumento,
    dataEmissao: dadosOriginais.dataEmissao
  }
}];

